//! Streaming search for literal byte sequences.

/// A literal match in the logical concatenation of the input chunks.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralMatch {
    /// The zero-based absolute byte offset at which the match begins.
    pub offset: u64,
}

/// The result of a streaming literal search.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LiteralSearchResult {
    /// The retained matches, ordered by ascending offset.
    pub matches: Vec<LiteralMatch>,
    /// Whether an additional match exists beyond the retained matches.
    pub truncated: bool,
    /// The number of input bytes examined.
    pub bytes_scanned: u64,
}

/// An error that prevents a literal search from completing.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum LiteralSearchError {
    /// The needle is empty.
    EmptyNeedle,
    /// The requested match limit is zero.
    ZeroMatchLimit,
    /// The absolute byte count cannot be represented by `u64`.
    OffsetOverflow,
}

fn build_prefix_table(needle: &[u8]) -> Vec<usize> {
    let mut table = vec![0; needle.len()];
    let mut border_length = 0_usize;

    for (index, &byte) in needle.iter().enumerate().skip(1) {
        while border_length > 0 && byte != needle[border_length] {
            border_length = table[border_length - 1];
        }

        if byte == needle[border_length] {
            border_length += 1;
        }

        table[index] = border_length;
    }

    table
}

/// Searches the logical concatenation of byte chunks for a literal byte sequence.
///
/// Matches may span chunk boundaries and may overlap. Scanning stops when the
/// complete input has been examined or when one match beyond `max_matches` has
/// been found.
///
/// # Errors
///
/// Returns [`LiteralSearchError::EmptyNeedle`] when `needle` is empty,
/// [`LiteralSearchError::ZeroMatchLimit`] when `max_matches` is zero, or
/// [`LiteralSearchError::OffsetOverflow`] when the absolute byte count cannot
/// fit in `u64`.
pub fn search_literal_chunks<'a, I>(
    chunks: I,
    needle: &[u8],
    max_matches: usize,
) -> Result<LiteralSearchResult, LiteralSearchError>
where
    I: IntoIterator<Item = &'a [u8]>,
{
    if needle.is_empty() {
        return Err(LiteralSearchError::EmptyNeedle);
    }
    if max_matches == 0 {
        return Err(LiteralSearchError::ZeroMatchLimit);
    }

    let Ok(needle_length) = u64::try_from(needle.len()) else {
        return Err(LiteralSearchError::OffsetOverflow);
    };
    let prefix_table = build_prefix_table(needle);
    let mut matches = Vec::new();
    let mut prefix_length = 0_usize;
    let mut bytes_scanned = 0_u64;

    for chunk in chunks {
        for &byte in chunk {
            bytes_scanned = bytes_scanned
                .checked_add(1)
                .ok_or(LiteralSearchError::OffsetOverflow)?;

            while prefix_length > 0 && byte != needle[prefix_length] {
                prefix_length = prefix_table[prefix_length - 1];
            }

            if byte == needle[prefix_length] {
                prefix_length += 1;
            }

            if prefix_length == needle.len() {
                if matches.len() == max_matches {
                    return Ok(LiteralSearchResult {
                        matches,
                        truncated: true,
                        bytes_scanned,
                    });
                }

                let offset = bytes_scanned
                    .checked_sub(needle_length)
                    .ok_or(LiteralSearchError::OffsetOverflow)?;
                matches.push(LiteralMatch { offset });
                prefix_length = prefix_table[prefix_length - 1];
            }
        }
    }

    Ok(LiteralSearchResult {
        matches,
        truncated: false,
        bytes_scanned,
    })
}
